base = from(bucket: "network_traffic")
  |> range(start: v.timeRangeStart, stop: v.timeRangeStop)
  |> filter(fn: (r) => r._measurement == "network_flow" and r._field == "bytes")
  |> filter(fn: (r) => r.src_ip =~ cidrRe or r.dst_ip =~ cidrRe)
  |> group(columns: ["src_ip"])

union(tables: [
  base |> sum()   |> map(fn: (r) => ({src_ip: r.src_ip, k: "bytes", v: r._value})),
  base |> count() |> map(fn: (r) => ({src_ip: r.src_ip, k: "flows", v: r._value})),
])
  |> group()
  |> pivot(rowKey: ["src_ip"], columnKey: ["k"], valueColumn: "v")
  |> map(fn: (r) => ({src_ip: r.src_ip, flows: r.flows, bytes: r.bytes,
                      mean: float(v: r.bytes) / float(v: r.flows)}))
  |> sort(columns: ["bytes"], desc: true)
  |> limit(n: 25)

